#!/bin/bash
# lib/heal.sh — auto-heal after SteamOS updates.
# Anchor: user systemd unit in /home (survives updates). Privilege bridge:
# scoped passwordless `svd repair` sudoers entry (regenerated by repair).

OS_RELEASE=/etc/os-release
STAMP="$SVD_ROOT/last-build.stamp"
SVD_BIN=/home/deck/.local/bin/svd
USER_UNIT_DIR=/home/deck/.config/systemd/user
USER_UNIT="${USER_UNIT:-$USER_UNIT_DIR/svd-heal.service}"
SUDOERS="${SUDOERS:-/etc/sudoers.d/svd-heal}"

heal_render_unit() {
  cat <<EOF
[Unit]
Description=SVD auto-heal after SteamOS update
After=graphical.target

[Service]
Type=oneshot
ExecStart=/bin/bash -lc 'sudo $SVD_BIN repair'

[Install]
WantedBy=default.target
EOF
}

heal_render_sudoers() {
  echo "deck ALL=(root) NOPASSWD: $SVD_BIN repair"
}

heal_install() {
  require_root
  local here="$1"
  log "Installing auto-heal (user unit + scoped sudoers)"
  run mkdir -p "$(dirname "$USER_UNIT")"
  if [ "$DRY_RUN" = "1" ]; then
    echo "DRY-RUN would write $USER_UNIT and $SUDOERS, enable svd-heal.service"
    return 0
  fi
  heal_render_unit > "$USER_UNIT"
  chown -R deck:deck "$(dirname "$USER_UNIT")"

  local tmp_sudoers
  tmp_sudoers="$(mktemp)"
  heal_render_sudoers > "$tmp_sudoers"
  chmod 0440 "$tmp_sudoers"
  if ! visudo -cf "$tmp_sudoers" >/dev/null; then
    rm -f "$tmp_sudoers"
    die "invalid sudoers file generated"
  fi
  install -m 0440 -o root -g root "$tmp_sudoers" "$SUDOERS"
  rm -f "$tmp_sudoers"

  sudo -u deck XDG_RUNTIME_DIR=/run/user/1000 systemctl --user daemon-reload \
    || log "WARNING: could not enable svd-heal.service now (no active user session?); it will be re-enabled on the next svd repair."
  sudo -u deck XDG_RUNTIME_DIR=/run/user/1000 systemctl --user enable svd-heal.service \
    || log "WARNING: could not enable svd-heal.service now (no active user session?); it will be re-enabled on the next svd repair."
}

# Called by the user unit on each boot.
heal_run() {
  local here="$1"
  if python3 "$here/helpers/build_id.py" changed "$OS_RELEASE" "$STAMP"; then
    log "SteamOS build changed (or first run) — repairing stack"
    "$SVD_BIN" repair
    python3 "$here/helpers/build_id.py" current "$OS_RELEASE" > "$STAMP"
    _notify "Virtual display repaired after update"
  else
    log "SteamOS build unchanged — no heal needed"
  fi
}

_notify() {
  command -v steamos-notify >/dev/null 2>&1 && steamos-notify "$1" || log "notify: $1"
}
